function validate([s, n]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's has 1 to 1000 characters.';
  if (!/^[01]+$/.test(s)) return "s contains only '0' and '1'.";
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is a whole number from 1 to 10^9.';
  return null;
}

