function queryString(s, n) {
  const seen = new Set();

  for (let start = 0; start < s.length; start++) {
    if (s[start] === '0') {
      continue;
    }
    let value = 0;
    for (let end = start; end < s.length; end++) {
      value = value * 2 + (s[end] === '1' ? 1 : 0);
      if (value > n) {
        break;
      }
      seen.add(value);
    }
  }
  return seen.size === n;
}

