function generate(rand, size) {
  const bits = length => Array.from({ length }, () => (rand() < 0.5 ? '0' : '1')).join('');
  // Concatenating the binary forms of (top / 2, top] covers every number up to top.
  const covering = top => {
    const parts = [];
    for (let x = Math.floor(top / 2) + 1; x <= top; x++) parts.push(x.toString(2));
    for (let i = parts.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [parts[i], parts[j]] = [parts[j], parts[i]];
    }
    return parts.join('');
  };
  if (size === 'large') {
    const pick = rand();
    if (pick < 0.65) {
      const top = 100 + Math.floor(rand() * 121);
      let s = covering(top);
      if (pick < 0.3) {
        // Damage one character so the answer may turn false.
        const at = Math.floor(rand() * s.length);
        s = s.slice(0, at) + (s[at] === '0' ? '1' : '0') + s.slice(at + 1);
      }
      const room = 1000 - s.length;
      const before = Math.floor(rand() * (room + 1));
      const n = Math.max(1, top - 3 + Math.floor(rand() * 6));
      return [bits(before) + s + bits(Math.floor(rand() * (room - before + 1))), n];
    }
    const n = Math.max(1, Math.floor(Math.pow(10, rand() * 9)));
    return [bits(1000), Math.min(n, 1000000000)];
  }
  if (rand() < 0.4) {
    const top = 1 + Math.floor(rand() * 8);
    const s = (bits(Math.floor(rand() * 3)) + covering(top)).slice(0, 14) || '1';
    return [s, Math.max(1, top - 1 + Math.floor(rand() * 3))];
  }
  return [bits(1 + Math.floor(rand() * 12)), 1 + Math.floor(rand() * 10)];
}
